INSERT INTO eventos (id, nombre, descripcion, fecha, activo, created_at, url_entradas, url_cartel, presentador, artista_invitado, votacion_activa, color_primario, color_secundario, color_fondo, color_texto, color_cabecera, participante_activo_id, puntuaciones_activas, pin_sesion, registro_pin_abierto, votos_totales_registrados, ronda_activa, limite_finalistas) VALUES ('396cb005-87f3-4a8b-ac87-684803246ac3', 'Poetry Slam Alicante VII Edición', 'Poetry Slam Alicante regresa en su VII Edición para transformar la Caja Negra de Las Cigarreras en un escenario de pura emoción compartida. Sobre las tablas, el latido de la ciudad toma forma en las voces de siete poetas que desnudarán sus versos ante un público entregado al magnetismo del directo.
